from html.parser import HTMLParser
from pathlib import Path
import hashlib
import json
import re

class RulePage(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.hidden = None
        self.text = []

    def handle_starttag(self, tag, attrs):
        if tag in {'style', 'script'}:
            self.hidden = tag
        if tag in {'p', 'dd', 'dt', 'td', 'th', 'tr', 'div', 'h1', 'h2', 'h3', 'pre', 'br', 'li'}:
            self.text.append('\n')

    def handle_endtag(self, tag):
        if tag == self.hidden:
            self.hidden = None
        if tag in {'p', 'dd', 'dt', 'td', 'th', 'tr', 'div', 'h1', 'h2', 'h3', 'pre', 'li'}:
            self.text.append('\n')

    def handle_data(self, data):
        if self.hidden is None:
            self.text.append(data)

base = Path('products/services/invoice-peppol-fit')
rules = {'BR-CO-10': '29e99135f017d8c43d3fa5a981c1fb09854fffc1809e9bd85962932942e9403b', 'BR-CO-13': 'c1660138ae7fe618b8aa19b866dbe9c14eab55a78801008e08b54e177af16a24'}
results = []
for rule, expected in rules.items():
    raw = (base / 'raw' / (rule.lower() + '.html')).read_bytes()
    actual = hashlib.sha256(raw).hexdigest()
    if actual != expected:
        results.append({'rule': rule, 'status': 'CAPTURE_HASH_MISMATCH', 'expected': expected, 'actual': actual})
        continue
    parser = RulePage()
    parser.feed(raw.decode('utf-8'))
    parser.close()
    lines = [' '.join(line.split()) for line in ''.join(parser.text).splitlines() if line.strip()]
    fields = {}
    for i, line in enumerate(lines):
        if line.rstrip(':').lower() in {'message', 'context', 'test'} and i + 1 < len(lines):
            fields.setdefault(line.rstrip(':').lower(), []).append(lines[i + 1])
    relevant = re.compile(r'BT-(?:106|107|108|109|131)\b|LineExtensionAmount|TaxExclusiveAmount|AllowanceTotalAmount|ChargeTotalAmount', re.I)
    excerpts = [line for line in lines if relevant.search(line)]
    results.append({'rule': rule, 'url': f'https://docs.peppol.eu/poacc/billing/3.0/rules/ubl-tc434/{rule}/', 'capture_sha256': actual, 'fields': fields, 'matching_visible_lines': excerpts, 'status': 'MESSAGE_AND_TEST_LOCATED' if fields.get('message') and fields.get('test') else 'MANUAL_SOURCE_CHECK_REQUIRED'})
report = {'scope': 'Whitespace-normalized visible source excerpts. Verify field boundaries against the original HTML before citing. Checker behavior requires separate execution.', 'rules': results}
output = base / 'director-rule-source-readback.json'
output.write_text(json.dumps(report, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(output.read_text(encoding='utf-8'))
